#include <iostream>
#include <cstdio>
using namespace std;

int count_digits_of(long long n) {
    int count = 0;
    while (n != 0) {
        n /= 10;
        count++;
    }
    return count;
}

long long largest_repeating_ones(long long n) {
    int length = count_digits_of(n);
    long long total = 0, base = 1;
    for (int i = 0; i < length; i++) {
        total += base;
        base *= 10;
    }
    if (total <= n) return total;
    return (total - 1) / 10;
}

long long solve_number(long long n) {
    if (n <= 6) return n;
    if (n <= 11) return 13 - n;
    long long base = largest_repeating_ones(n);
    long long next_value = base * 10 + 1;
    if (n % base == 0) {
        if (n <= (next_value / 2 + base))
            return count_digits_of(base) * n / base;
        return count_digits_of(next_value) + solve_number(next_value - n);
    } else {
        long long m = (n / base) * base;
        long long res = solve_number(m) + solve_number(n - m);
        if (n > next_value / 2)
            res = min(solve_number(m) + solve_number(n - m), count_digits_of(next_value) + solve_number(next_value - n));
        return res;
    }
}

int main() {
    long long n;
    cin >> n;
    cout << solve_number(n) << endl;
