def solve_number(n):
    if n <= 6:
        return n
    if n <= 11:
        return 13 - n
    base = largest_repeating_ones(n)
    next_value = base * 10 + 1
    if n % base == 0:
        if n <= (next_value // 2 + base):
            return count_digits_of(base) * n // base
        return count_digits_of(next_value) + solve_number(next_value - n)
    else:
        m = (n // base) * base
        res = solve_number(m) + solve_number(n - m)
        if n > next_value // 2:
            res = min(solve_number(m) + solve_number(n - m),
                      count_digits_of(next_value) + solve_number(next_value - n))
